use std::time::Duration;
/// Split a delay into a fixed half and a random half — "equal jitter".
///
/// WHY JITTER AT ALL: exponential backoff without it SYNCHRONISES. N workers that hit one rate limit
/// in the same instant compute the same delay and retry in the same instant, so the second burst is
/// as sharp as the first. Jitter is what turns a delay into a spread, and it is the property that
/// matters at N concurrent clients rather than at one.
///
/// WHY EQUAL AND NOT FULL JITTER: full jitter draws from `[0, base]`, so a client can retry almost
/// immediately after the server asked it to slow down. Keeping half the delay fixed preserves the
/// backoff's meaning while still decorrelating the clients.
///
/// PURE, with `entropy` injected, so the spread is provable without depending on a clock.
pub(crate) fn jittered(base: Duration, entropy: u64) -> Duration {
    let half = base / 2;
    let span = half.as_nanos() as u64;
    if span == 0 {
        return base; // a zero or sub-2ns base has nothing to spread; tests pass ZERO deliberately
    }
    half + Duration::from_nanos(entropy % span)
}
